SELECT 
FROM xxl_boot_dict_item AS t
WHERE t.`id` = #{id}

SELECT 
FROM xxl_boot_dict_item AS t

    t.`dict_id` = #{dictId}

        AND t.`name` like CONCAT(CONCAT('%', #{name}), '%')


        AND t.`status` = #{status}


ORDER BY t.`order` ASC, t.`id` DESC
LIMIT #{offset}, #{pagesize}

SELECT count(1)
FROM xxl_boot_dict_item AS t

    t.`dict_id` = #{dictId}

        AND t.`name` like CONCAT(CONCAT('%', #{name}), '%')


        AND t.`status` = #{status}
